import { divide, factorial, clamp } from './math';

describe('divide', () => {
  it('divides two numbers', () => expect(divide(10, 2)).toBe(5));
  it('handles negative numbers', () => expect(divide(-10, 2)).toBe(-5));
});

describe('clamp', () => {
  it('clamps value below min', () => expect(clamp(0, 1, 10)).toBe(1));
  it('clamps value above max', () => expect(clamp(100, 1, 10)).toBe(10));
  it('passes value in range', () => expect(clamp(5, 1, 10)).toBe(5));
});
